#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#include <gkyl_alloc.h>
#include <gkyl_gyrokinetic.h>
#include <gkyl_gyrokinetic_run.h>
#include <gkyl_util.h>

#include <rt_arg_parse.h>

struct sodshock_ctx {
  int cdim, vdim; // Dimensionality.

  // Physical constants (using normalized code units).
  double mass; // Neutral mass.
  double charge; // Neutral charge.

  double nl; // Left number density.
  double Tl; // Left temperature.

  double nr; // Right number density.
  double Tr; // Right temperature.

  double B0; // Reference magnetic field strength.
  double n0; // Reference number density.
  double vt; // Reference thermal velocity.
  double nu; // Collision frequency.

  // Simulation parameters.
  int Nz; // Cell count (configuration space: z-direction).
  int Nvpar; // Cell count (velocity space: parallel velocity direction).
  int Nmu; // Cell count (velocity space: magnetic moment direction).
  int cells[GKYL_MAX_DIM]; // Number of cells in all directions.
  double Lz; // Domain size (configuration space: z-direction).
  double vpar_max; // Domain boundary (velocity space: parallel velocity direction).
  double mu_max; // Domain boundary (velocity space: magnetic moment direction).
  int poly_order; // Polynomial order.
  double cfl_frac; // CFL coefficient.

  double t_end; // End time.
  int num_frames; // Number of output frames.
  double
    write_phase_freq; // Frequency of writing phase-space diagnostics (as a fraction of num_frames).
  int int_diag_calc_num; // Number of integrated diagnostics computations (=INT_MAX for every step).
  double dt_failure_tol; // Minimum allowable fraction of initial time-step.
  int num_failures_max; // Maximum allowable number of consecutive small time-steps.
};

struct sodshock_ctx create_ctx(void)
{
  int cdim = 1, vdim = 2; // Dimensionality.

  // Physical constants (using normalized code units).
  double mass = 1.0; // Neutral mass.
  double charge = 0.0; // Neutral charge.

  double nl = 1.0; // Left number density.
  double Tl = 1.0; // Left temperature.

  double nr = 0.125; // Right number density.
  double Tr = sqrt(0.1 / 0.125); // Right temperature.

  double B0 = 1.0; // Reference magnetic field strength.
  double n0 = 1.0; // Reference number density.
  double vt = 1.0; // Reference thermal velocity.
  double nu = 100.0; // Collision frequency.

  // Simulation parameters.
  int Nz = 64; // Cell count (configuration space: z-direction).
  int Nvpar = 16; // Cell count (velocity space: parallel velocity direction).
  int Nmu = 16; // Cell count (velocity space: magnetic moment direction).
  double Lz = 2.0; // Domain size (configuration space: x-direction).
  double vpar_max = 6.0 * vt; // Domain boundary (velocity space: parallel velocity direction).
  double mu_max =
    18.0 * (vt * vt) / 2.0 / B0; // Domain boundary (velocity space: magnetic moment direction).
  int poly_order = 1; // Polynomial order.
  double cfl_frac = 1.0; // CFL coefficient.

  double t_end = 0.1; // Final simulation time.
  int num_frames = 1; // Number of output frames.
  double write_phase_freq =
    0.2; // Frequency of writing phase-space diagnostics (as a fraction of num_frames).
  int int_diag_calc_num = num_frames * 100;
  double dt_failure_tol = 1.0e-4; // Minimum allowable fraction of initial time-step.
  int num_failures_max = 20; // Maximum allowable number of consecutive small time-steps.

  struct sodshock_ctx ctx = {
    .cdim = cdim,
    .vdim = vdim,
    .mass = mass,
    .charge = charge,
    .nl = nl,
    .Tl = Tl,
    .nr = nr,
    .Tr = Tr,
    .B0 = B0,
    .n0 = n0,
    .vt = vt,
    .nu = nu,
    .Nz = Nz,
    .Nvpar = Nvpar,
    .Nmu = Nmu,
    .cells = {Nz, Nvpar, Nmu},
    .Lz = Lz,
    .vpar_max = vpar_max,
    .mu_max = mu_max,
    .poly_order = poly_order,
    .cfl_frac = cfl_frac,
    .t_end = t_end,
    .num_frames = num_frames,
    .write_phase_freq = write_phase_freq,
    .int_diag_calc_num = int_diag_calc_num,
    .dt_failure_tol = dt_failure_tol,
    .num_failures_max = num_failures_max
  };

  return ctx;
}

void evalDensityInit(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  struct sodshock_ctx *app = ctx;
  double z = xn[0];

  double nl = app->nl;
  double nr = app->nr;

  double n = 0.0;

  if (fabs(z) < 0.5) {
    n = nl; // Total number density (left).
  } else {
    n = nr; // Total number density (right).
  }

  // Set total number density.
  fout[0] = n;
}

void evalTempInit(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  struct sodshock_ctx *app = ctx;
  double z = xn[0];

  double Tl = app->Tl;
  double Tr = app->Tr;

  double T = 0.0;

  if (fabs(z) < 0.5) {
    T = Tl; // Isotropic temperature (left).
  } else {
    T = Tr; // Isotropic temperature (right).
  }

  // Set isotropic temperature.
  fout[0] = T;
}

void evalUparInit(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  // Set parallel velocity.
  fout[0] = 0.0;
}

void evalNu(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  struct sodshock_ctx *app = ctx;

  double nu = app->nu;

  // Set collision frequency.
  fout[0] = nu;
}

static inline void
mapc2p(double t, const double *GKYL_RESTRICT zc, double *GKYL_RESTRICT xp, void *ctx)
{
  // Set physical coordinates (X, Y, Z) from computational coordinates (x, y, z).
  xp[0] = zc[0];
  xp[1] = zc[1];
  xp[2] = zc[2];
}

void bfield_func(double t, const double *GKYL_RESTRICT zc, double *GKYL_RESTRICT fout, void *ctx)
{
  struct sodshock_ctx *app = ctx;

  double B0 = app->B0;

  // zc are computational coords.
  // Set Cartesian components of magnetic field.
  fout[0] = 0.0;
  fout[1] = 0.0;
  fout[2] = app->B0;
}

