    double *out_d = gkyl_array_fetch(out, linidx);

    double *prim_vars_d = up->is_integrated ? prim_vars_buff : &out_d[out_coff];

    double *udrift_d = prim_vars_d;
    double *pressure_d = &prim_vars_d[up->udrift_ncomp * up->num_basis];

