struct gkyl_gk_maxwellian_moments *
gkyl_gk_maxwellian_moments_inew(const struct gkyl_gk_maxwellian_moments_inp *inp)
{
  gkyl_gk_maxwellian_moments *up = gkyl_malloc(sizeof(*up));

  up->conf_basis = *inp->conf_basis;
  up->phase_basis = *inp->phase_basis;
  up->num_conf_basis = inp->conf_basis->num_basis;
  int vdim = up->phase_basis.ndim - up->conf_basis.ndim;

  // Determine factor to divide out of temperature computation
  // If 1x1v, up->vdim_phys = 1, otherwise up->vdim_phys = 3.
  up->vdim_phys = 2 * vdim - 1;
  up->gk_geom = gkyl_gk_geometry_acquire(inp->gk_geom);
  up->divide_jacobgeo = inp->divide_jacobgeo;

  long conf_range_ncells = inp->conf_range->volume;
  long conf_range_ext_ncells = inp->conf_range_ext->volume;

  if (inp->use_gpu) {
    up->M0 = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->M1 = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->u_par = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->u_par_dot_M1 =
      gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->pressure = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->temperature = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    // Bin op memory for needed weak divisions
    up->mem = gkyl_dg_bin_op_mem_cu_dev_new(conf_range_ncells, up->num_conf_basis);
    if (vdim == 2) {
      // Additional moments if computing Bi-Maxwellian moments (Tpar, Tperp)
      up->p_par = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
      up->t_par = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
      up->p_perp = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
      up->t_perp = gkyl_array_cu_dev_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    }
  } else {
    up->M0 = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->M1 = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->u_par = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->u_par_dot_M1 = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->pressure = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    up->temperature = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    // Bin op memory for needed weak divisions
    up->mem = gkyl_dg_bin_op_mem_new(conf_range_ncells, up->num_conf_basis);
    if (vdim == 2) {
      // Additional moments if computing Bi-Maxwellian moments (Tpar, Tperp)
      up->p_par = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
      up->t_par = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
      up->p_perp = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
      up->t_perp = gkyl_array_new(GKYL_DOUBLE, up->num_conf_basis, conf_range_ext_ncells);
    }
  }

  // Moment calculator for needed moments (M0, M1, and M2)
  up->M0_calc = gkyl_dg_updater_moment_gyrokinetic_new(
    inp->phase_grid, inp->conf_basis, inp->phase_basis, inp->conf_range, inp->mass, 0, inp->vel_map,
    inp->gk_geom, NULL, GKYL_F_MOMENT_M0, 0, inp->use_gpu
  );
  up->M1_calc = gkyl_dg_updater_moment_gyrokinetic_new(
    inp->phase_grid, inp->conf_basis, inp->phase_basis, inp->conf_range, inp->mass, 0, inp->vel_map,
    inp->gk_geom, NULL, GKYL_F_MOMENT_M1, 0, inp->use_gpu
  );
  up->M2_calc = gkyl_dg_updater_moment_gyrokinetic_new(
    inp->phase_grid, inp->conf_basis, inp->phase_basis, inp->conf_range, inp->mass, 0, inp->vel_map,
    inp->gk_geom, NULL, GKYL_F_MOMENT_M2, 0, inp->use_gpu
  );

  if (vdim == 2) {
    // Additional moment calculators for Bi-Maxwellian moments (M2par, M2perp)
    up->M2_par_calc = gkyl_dg_updater_moment_gyrokinetic_new(
      inp->phase_grid, inp->conf_basis, inp->phase_basis, inp->conf_range, inp->mass, 0,
      inp->vel_map, inp->gk_geom, NULL, GKYL_F_MOMENT_M2PAR, 0, inp->use_gpu
    );
    up->M2_perp_calc = gkyl_dg_updater_moment_gyrokinetic_new(
      inp->phase_grid, inp->conf_basis, inp->phase_basis, inp->conf_range, inp->mass, 0,
      inp->vel_map, inp->gk_geom, NULL, GKYL_F_MOMENT_M2PERP, 0, inp->use_gpu
    );
  }

  return up;
}

void gkyl_gk_maxwellian_density_moment_advance(
  struct gkyl_gk_maxwellian_moments *up, const struct gkyl_range *phase_range,
  const struct gkyl_range *conf_range, const struct gkyl_array *fin, struct gkyl_array *density_out
)
{
  // compute J*M0 where J is the configurations-space Jacobian
  gkyl_dg_updater_moment_gyrokinetic_advance(up->M0_calc, phase_range, conf_range, fin, up->M0);
  if (up->divide_jacobgeo) {
    // Rescale moment by the inverse of the Jacobian
    gkyl_dg_div_op_range(
      up->mem, &up->conf_basis, 0, density_out, 0, up->M0, 0, up->gk_geom->geo_int.jacobgeo,
      conf_range
    );
  } else {
    gkyl_array_set_range(density_out, 1.0, up->M0, conf_range);
  }
}

void gkyl_gk_maxwellian_moments_advance(
  struct gkyl_gk_maxwellian_moments *up, const struct gkyl_range *phase_range,
  const struct gkyl_range *conf_range, const struct gkyl_array *fin, struct gkyl_array *moms_out
)
{
  // compute J*M0 and J*M1 where J is the configurations-space Jacobian
  gkyl_dg_updater_moment_gyrokinetic_advance(up->M0_calc, phase_range, conf_range, fin, up->M0);
  gkyl_dg_updater_moment_gyrokinetic_advance(up->M1_calc, phase_range, conf_range, fin, up->M1);

  // Isolate u_par by dividing J*M1 by J*M0
  gkyl_dg_div_op_range(up->mem, &up->conf_basis, 0, up->u_par, 0, up->M1, 0, up->M0, conf_range);

  // Compute J*M1*upar (needed to compute T/m).
  gkyl_dg_mul_op_range(&up->conf_basis, 0, up->u_par_dot_M1, 0, up->u_par, 0, up->M1, conf_range);

  // Compute J*M2 = vdim_phys*J*n*T/m + J*M1*upar.
  gkyl_dg_updater_moment_gyrokinetic_advance(
    up->M2_calc, phase_range, conf_range, fin, up->pressure
  );
  // Subtract off J*M1*upar from total J*M2
  gkyl_array_accumulate_range(up->pressure, -1.0, up->u_par_dot_M1, conf_range);

  // Rescale J*n*T by 1.0/vdim_phys and divide out J*M0 to get T/m, T/m = J*P/(m J*M0).
  gkyl_array_scale(up->pressure, 1.0 / up->vdim_phys);
  gkyl_dg_div_op_range(
    up->mem, &up->conf_basis, 0, up->temperature, 0, up->pressure, 0, up->M0, conf_range
  );

  if (up->divide_jacobgeo) {
    // Rescale moment by the inverse of the Jacobian and store in moms_out
    gkyl_dg_div_op_range(
      up->mem, &up->conf_basis, 0, moms_out, 0, up->M0, 0, up->gk_geom->geo_int.jacobgeo, conf_range
    );
  } else {
    gkyl_array_set_range(moms_out, 1.0, up->M0, conf_range);
  }
  // Save the other outputs to moms_out (n, V_drift, T/m):
  int num_conf_basis = up->num_conf_basis;
  gkyl_array_set_offset_range(moms_out, 1.0, up->u_par, 1 * num_conf_basis, conf_range);
  gkyl_array_set_offset_range(moms_out, 1.0, up->temperature, 2 * num_conf_basis, conf_range);
}

void gkyl_gk_bimaxwellian_moments_advance(
  struct gkyl_gk_maxwellian_moments *up, const struct gkyl_range *phase_range,
  const struct gkyl_range *conf_range, const struct gkyl_array *fin, struct gkyl_array *moms_out
)
{
  // compute J*M0 and J*M1 where J is the configurations-space Jacobian
  gkyl_dg_updater_moment_gyrokinetic_advance(up->M0_calc, phase_range, conf_range, fin, up->M0);
  gkyl_dg_updater_moment_gyrokinetic_advance(up->M1_calc, phase_range, conf_range, fin, up->M1);

  // Isolate u_par by dividing J*M1 by J*M0
  gkyl_dg_div_op_range(up->mem, &up->conf_basis, 0, up->u_par, 0, up->M1, 0, up->M0, conf_range);

  // Compute J*M1*upar (needed to compute T_par/m).
  gkyl_dg_mul_op_range(&up->conf_basis, 0, up->u_par_dot_M1, 0, up->u_par, 0, up->M1, conf_range);

  // Compute J*M2_par = J*n*T_par/m + J*M1*upar.
  gkyl_dg_updater_moment_gyrokinetic_advance(
    up->M2_par_calc, phase_range, conf_range, fin, up->p_par
  );
  // Subtract off J*M1*upar from total J*M2_par
  gkyl_array_accumulate_range(up->p_par, -1.0, up->u_par_dot_M1, conf_range);

  // Compute J*M2_perp = 2*J*n*T_perp/m.
  gkyl_dg_updater_moment_gyrokinetic_advance(
    up->M2_perp_calc, phase_range, conf_range, fin, up->p_perp
  );

  // Rescale J*n*T_perp by 1/2 and divide out J*M0 to get T_par/m, T_perp/m
  // from n*T_par/m, n*T_perp/m.
  gkyl_array_scale(up->p_perp, 0.5);
  gkyl_dg_div_op_range(up->mem, &up->conf_basis, 0, up->t_par, 0, up->p_par, 0, up->M0, conf_range);
  gkyl_dg_div_op_range(
    up->mem, &up->conf_basis, 0, up->t_perp, 0, up->p_perp, 0, up->M0, conf_range
  );

  if (up->divide_jacobgeo) {
    // Rescale moment by the inverse of the Jacobian and store in moms_out
    gkyl_dg_div_op_range(
      up->mem, &up->conf_basis, 0, moms_out, 0, up->M0, 0, up->gk_geom->geo_int.jacobgeo, conf_range
    );
  } else {
    gkyl_array_set_range(moms_out, 1.0, up->M0, conf_range);
  }
  // Save the other outputs to moms_out (n, u_par, T_par/m, T_perp/m):
  int num_conf_basis = up->num_conf_basis;
  gkyl_array_set_offset_range(moms_out, 1.0, up->u_par, 1 * num_conf_basis, conf_range);
  gkyl_array_set_offset_range(moms_out, 1.0, up->t_par, 2 * num_conf_basis, conf_range);
  gkyl_array_set_offset_range(moms_out, 1.0, up->t_perp, 3 * num_conf_basis, conf_range);
}

void gkyl_gk_maxwellian_moments_release(gkyl_gk_maxwellian_moments *up)
{
  gkyl_gk_geometry_release(up->gk_geom);
  gkyl_array_release(up->M0);
  gkyl_array_release(up->M1);
  gkyl_array_release(up->u_par);
  gkyl_array_release(up->u_par_dot_M1);
  gkyl_array_release(up->pressure);
  gkyl_array_release(up->temperature);
  gkyl_dg_bin_op_mem_release(up->mem);

  gkyl_dg_updater_moment_gyrokinetic_release(up->M0_calc);
  gkyl_dg_updater_moment_gyrokinetic_release(up->M1_calc);
  gkyl_dg_updater_moment_gyrokinetic_release(up->M2_calc);
  if (up->vdim_phys == 3) {
    gkyl_array_release(up->p_par);
    gkyl_array_release(up->t_par);
    gkyl_array_release(up->p_perp);
    gkyl_array_release(up->t_perp);
    gkyl_dg_updater_moment_gyrokinetic_release(up->M2_par_calc);
    gkyl_dg_updater_moment_gyrokinetic_release(up->M2_perp_calc);
  }

  gkyl_free(up);
}
    }
    lower_bcdir_ext[par_dir] = gks->local_ext_core.lower[par_dir];
    upper_bcdir_ext[par_dir] = gks->local_ext_core.upper[par_dir];
    gkyl_sub_range_init(
      &gks->local_par_ext_core, &gks->local_ext_core, lower_bcdir_ext, upper_bcdir_ext
    );
  }

  // Initialize boundary fluxes.
  gks->bflux = (struct gk_boundary_fluxes){};
  // Additional bflux moments to step in time.
  struct gkyl_phase_diagnostics_inp add_bflux_moms_inp = (struct gkyl_phase_diagnostics_inp){};
  enum gkyl_species_bflux_type bflux_type = GK_SPECIES_BFLUX_NONE;
  // Check if using Boltzmann elc.
  bool ion_in_boltz_elc_field = (gks->info.charge > 0.0) && app->field->update_field &&
                                (app->field->gkfield_id == GKYL_GK_FIELD_BOLTZMANN);
  // Check if sources are adaptive.
  bool adaptive_sources = gk_species_do_I_adapt_src(app, gks);
  // Check if other species use the recycle_react_scale operation.
  bool recycle_react_scale = gk_species_do_I_recycle_react_scale(app, gks);
  // Check if other species have recycling BCs.
  bool recycling_bcs = gk_species_do_I_recycle(app, gks);
  if (gks->info.boundary_flux_diagnostics.num_diag_moments > 0 ||
      gks->info.boundary_flux_diagnostics.num_integrated_diag_moments > 0) {
    bflux_type = GK_SPECIES_BFLUX_CALC_FLUX_STEP_MOMS_DIAGS;
  } else {
    // Set bflux_type to
    //   - GK_SPECIES_BFLUX_CALC_FLUX to only put bfluxes in ghost cells of rhs.
    //   - GK_SPECIES_BFLUX_CALC_FLUX_STEP_MOMS to calc bfluxes and step its moments.
    // The latter also requires that you place the moment you desire in add_bflux_moms_inp below.

    if (recycling_bcs) {
      bflux_type = GK_SPECIES_BFLUX_CALC_FLUX;
    }
    if (ion_in_boltz_elc_field || adaptive_sources || recycle_react_scale) {
      // This is within an if-statement instead of an else if because it
      // superseeds (and is a superset) of GK_SPECIES_BFLUX_CALC_FLUX.
      bflux_type = GK_SPECIES_BFLUX_CALC_FLUX_STEP_MOMS;
    }
  }
  int *nmom_extra = &add_bflux_moms_inp.num_diag_moments;
  if (ion_in_boltz_elc_field || adaptive_sources || recycle_react_scale) {
    add_bflux_moms_inp.diag_moments[nmom_extra[0]++] = GKYL_F_MOMENT_M0;
  }
  if (adaptive_sources) {
    add_bflux_moms_inp.diag_moments[nmom_extra[0]++] = GKYL_F_MOMENT_M2;
  }
  // Introduce new moments into moms_inp if needed.
  gk_species_bflux_init(app, gks, &gks->bflux, bflux_type, add_bflux_moms_inp);

  // Initialize empty structs. New methods will fill them if specified.
  gks->src = (struct gk_source){};
  gks->rad = (struct gk_rad_drag){};

  // Initialize a Maxwellian/LTE (local thermodynamic equilibrium) projection routine
  // Projection routine optionally corrects all the Maxwellian/LTE moments
  // This routine is utilized by both reactions and BGK collisions
  gks->lte = (struct gk_lte){};
  bool correct_all_moms = gks->info.correct.correct_all_moms;
  int max_iter = gks->info.correct.max_iter > 0 ? gks->info.correct.max_iter : 50;
  double iter_eps = gks->info.correct.iter_eps > 0 ? gks->info.correct.iter_eps : 1e-10;
  bool use_last_converged = gks->info.correct.use_last_converged;
  struct correct_all_moms_inp corr_inp = {
    .correct_all_moms = correct_all_moms,
    .max_iter = max_iter,
    .iter_eps = iter_eps,
    .use_last_converged = use_last_converged
  };
  gk_species_lte_init(app, gks, &gks->lte, corr_inp);

  // Initialize the object that scales the species (meant for fluid neutrals for now).
  gks->sca = (struct gk_scaling){};
  gk_species_scaling_init(app, gks, &gks->sca);

  // Initialize reactions with charged species.
  gks->react = (struct gk_react){};
  gk_species_react_init(app, gks, gks->info.react, &gks->react, true);

  // Initialize reactions with neutral species.
  gks->react_neut = (struct gk_react){};
  gk_species_react_init(app, gks, gks->info.react_neut, &gks->react_neut, false);

  // Initialize LBO collisions.
  gks->lbo = (struct gk_lbo_collisions){};
  gk_species_lbo_init(app, gks, &gks->lbo);

  // Initialize BGK collisions.
  gks->bgk = (struct gk_bgk_collisions){};
  gk_species_bgk_init(app, gks, &gks->bgk);

  // Initialize a BGK source.
  gks->bgk_src = (struct gk_source_bgk){};
  gk_species_source_bgk_init(app, gks, &gks->bgk_src);

  // Initialize positivity enforcing operator.
  gks->positivity = (struct gk_positivity){};
  gk_species_positivity_init(app, gks, &gks->positivity);

  if (gks->info.is_static) {
    gk_species_init_static(gk_app_inp, app, gks);
  } else {
    gk_species_init_dynamic(gk_app_inp, app, gks);
  }
}

