  gkyl_gyrokinetic_app *app, const struct gk_species *species, struct gk_bgk_collisions *bgk
)
{
  // Calculate nu_ss(x,t).
  gkyl_spitzer_coll_freq_advance_normnu(
    bgk->spitzer_calc, &app->local, species->lte.moms.marr, bgk->vtsq_min, species->lte.moms.marr,
    bgk->vtsq_min, bgk->norm_nu_fac_self, bgk->self_nu
  );

