static void gkbgk_cross_nu_calc_normNu(
  gkyl_gyrokinetic_app *app, const struct gk_species *s, struct gk_bgk_collisions *bgk, int coll_idx
)
{
  // Calculate nu_sr(x,t).
  gkyl_spitzer_coll_freq_advance_normnu(
